'use strict';

/**
 * Thrown by `ShoppingCart#removeItem` when no line item has the given name.
 * `itemName` holds the name that was not found, so callers can report it
 * without parsing the message.
 */
class CartItemNotFoundError extends Error {
  /**
   * @param {string} itemName
   */
  constructor(itemName) {
    super(`Cannot remove ${JSON.stringify(itemName)}: no item with that name is in the cart`);
    this.name = 'CartItemNotFoundError';
    this.itemName = itemName;
  }
}

module.exports = { CartItemNotFoundError };

