'use strict';

const { describe, it, beforeEach } = require('node:test');
const assert = require('node:assert/strict');

const ShoppingCart = require('../src/cart');
const { CartItemNotFoundError } = require('../src/errors');

// Prices below are exactly representable in binary floating point, so totals
// can be compared with strict equality.

describe('ShoppingCart', () => {
  let cart;

  beforeEach(() => {
    cart = new ShoppingCart();
  });

  describe('addItem', () => {
    it('adds a new item as its own line', () => {
      cart.addItem('apple', 1.5, 2);

      assert.equal(cart.getItemCount(), 1);
      assert.deepEqual(cart.items, [{ name: 'apple', price: 1.5, quantity: 2 }]);
    });

    it('merges the quantity when the same name is added again', () => {
      cart.addItem('apple', 1.5, 2);
      cart.addItem('apple', 1.5, 3);

      assert.equal(cart.getItemCount(), 1);
      assert.equal(cart.items[0].quantity, 5);
    });

    it('keeps the first price when the same name is added again at a different price', () => {
      cart.addItem('apple', 1.5, 1);
      cart.addItem('apple', 9, 1);

      assert.equal(cart.items[0].price, 1.5);
      assert.equal(cart.getTotal(), 3);
    });

    it('accepts a price of zero for free items', () => {
      cart.addItem('sticker', 0, 4);

      assert.equal(cart.getTotal(), 0);
      assert.equal(cart.getItemCount(), 1);
    });

    it('accepts a quantity of exactly one', () => {
      cart.addItem('apple', 2, 1);

      assert.equal(cart.getTotal(), 2);
    });

    it('bug 1: rejects a negative price with a RangeError', () => {
      assert.throws(() => cart.addItem('apple', -1, 1), {
        name: 'RangeError',
        message: /price.*-1/i,
      });
      assert.equal(cart.getItemCount(), 0);
    });

    it('bug 1: rejects a negative quantity with a RangeError', () => {
      assert.throws(() => cart.addItem('apple', 1, -2), {
        name: 'RangeError',
        message: /quantity.*-2/i,
      });
      assert.equal(cart.getItemCount(), 0);
    });

    it('bug 1: a negative quantity cannot shrink an existing line', () => {
      cart.addItem('apple', 1, 5);

      assert.throws(() => cart.addItem('apple', 1, -3), RangeError);
      assert.equal(cart.items[0].quantity, 5);
    });

    it('rejects a quantity of zero', () => {
      assert.throws(() => cart.addItem('apple', 1, 0), RangeError);
      assert.equal(cart.getItemCount(), 0);
    });

    it('rejects a fractional quantity', () => {
      assert.throws(() => cart.addItem('apple', 1, 1.5), RangeError);
    });

    for (const [label, price] of [
      ['NaN', NaN],
      ['Infinity', Infinity],
      ['a numeric string', '10'],
      ['undefined', undefined],
    ]) {
      it(`rejects ${label} as a price with a TypeError`, () => {
        assert.throws(() => cart.addItem('apple', price, 1), TypeError);
        assert.equal(cart.getItemCount(), 0);
      });
    }

    for (const [label, quantity] of [
      ['NaN', NaN],
      ['a numeric string', '2'],
      ['undefined (omitted)', undefined],
    ]) {
      it(`rejects ${label} as a quantity with a TypeError`, () => {
        assert.throws(() => cart.addItem('apple', 1, quantity), TypeError);
        assert.equal(cart.getItemCount(), 0);
      });
    }

    it('rejects a non-string name with a TypeError', () => {
      assert.throws(() => cart.addItem(42, 1, 1), TypeError);
    });

    it('rejects an empty or whitespace-only name with a RangeError', () => {
      assert.throws(() => cart.addItem('', 1, 1), RangeError);
      assert.throws(() => cart.addItem('   ', 1, 1), RangeError);
      assert.equal(cart.getItemCount(), 0);
    });
  });

  describe('removeItem', () => {
    beforeEach(() => {
      cart.addItem('apple', 1, 2);
      cart.addItem('banana', 0.5, 4);
      cart.addItem('cherry', 3, 1);
    });

    it('bug 2: removes only the named item and keeps the others', () => {
      cart.removeItem('banana');

      assert.deepEqual(
        cart.items.map((item) => item.name),
        ['apple', 'cherry'],
      );
      assert.equal(cart.getTotal(), 5);
    });

    it('bug 2: does not rename the remaining items to the removed name', () => {
      cart.removeItem('apple');

      for (const item of cart.items) {
        assert.notEqual(item.name, 'apple');
      }
    });

    it('bug 2: throws CartItemNotFoundError for an item that is not in the cart', () => {
      assert.throws(
        () => cart.removeItem('durian'),
        (error) => {
          assert.ok(error instanceof CartItemNotFoundError);
          assert.equal(error.itemName, 'durian');
          assert.match(error.message, /durian/);
          return true;
        },
      );
    });

    it('leaves the cart unchanged when the item is not found', () => {
      assert.throws(() => cart.removeItem('durian'), CartItemNotFoundError);

      assert.equal(cart.getItemCount(), 3);
      assert.equal(cart.getTotal(), 7);
    });

    it('removes the whole line, including merged quantities', () => {
      cart.addItem('apple', 1, 10);
      cart.removeItem('apple');

      assert.equal(cart.getItemCount(), 2);
      assert.equal(cart.getTotal(), 5);
    });

    it('throws when the same item is removed twice', () => {
      cart.removeItem('cherry');

      assert.throws(() => cart.removeItem('cherry'), CartItemNotFoundError);
      assert.equal(cart.getItemCount(), 2);
    });

    it('empties the cart when every item is removed', () => {
      cart.removeItem('apple');
      cart.removeItem('banana');
      cart.removeItem('cherry');

      assert.equal(cart.getItemCount(), 0);
      assert.equal(cart.getTotal(), 0);
    });

    it('matches names exactly and case-sensitively', () => {
      assert.throws(() => cart.removeItem('Apple'), CartItemNotFoundError);
      assert.equal(cart.getItemCount(), 3);
    });

    it('rejects a non-string name with a TypeError', () => {
      assert.throws(() => cart.removeItem(undefined), TypeError);
      assert.equal(cart.getItemCount(), 3);
    });
  });

  describe('getTotal', () => {
    it('returns 0 for an empty cart', () => {
      assert.equal(cart.getTotal(), 0);
    });

    it('bug 3: stops at the last item instead of reading past the end', () => {
      cart.addItem('apple', 2, 3);

      assert.doesNotThrow(() => cart.getTotal());
      assert.equal(cart.getTotal(), 6);
    });

    it('sums price times quantity across every line', () => {
      cart.addItem('apple', 2, 3);
      cart.addItem('banana', 0.25, 4);
      cart.addItem('cherry', 10, 1);

      assert.equal(cart.getTotal(), 17);
    });

    it('bug 4: subtracts the discount instead of adding it', () => {
      cart.addItem('widget', 50, 2);
      cart.applyDiscount(10);

      assert.equal(cart.getTotal(), 90);
    });

    it('bug 4: a discounted total is never above the undiscounted total', () => {
      cart.addItem('widget', 40, 1);
      const undiscounted = cart.getTotal();
      cart.applyDiscount(25);

      assert.equal(cart.getTotal(), 30);
      assert.ok(cart.getTotal() < undiscounted);
    });

    it('returns the full total with a 0% discount', () => {
      cart.addItem('widget', 40, 1);
      cart.applyDiscount(0);

      assert.equal(cart.getTotal(), 40);
    });

    it('returns 0 with a 100% discount', () => {
      cart.addItem('widget', 40, 1);
      cart.applyDiscount(100);

      assert.equal(cart.getTotal(), 0);
    });

    it('applies the discount to items added after it', () => {
      cart.applyDiscount(50);
      cart.addItem('widget', 40, 1);

      assert.equal(cart.getTotal(), 20);
    });

    it('does not change the stored items when called', () => {
      cart.addItem('widget', 40, 2);
      cart.applyDiscount(50);
      const before = structuredClone(cart.items);

      cart.getTotal();
      cart.getTotal();

      assert.deepEqual(cart.items, before);
    });
  });

  describe('applyDiscount', () => {
    beforeEach(() => {
      cart.addItem('widget', 80, 1);
    });

    it('accepts the 0 and 100 boundaries', () => {
      assert.doesNotThrow(() => cart.applyDiscount(0));
      assert.doesNotThrow(() => cart.applyDiscount(100));
      assert.equal(cart.getTotal(), 0);
    });

    it('accepts a fractional percentage', () => {
      cart.applyDiscount(12.5);

      assert.equal(cart.getTotal(), 70);
    });

    it('bug 5: rejects a discount above 100 with a RangeError', () => {
      assert.throws(() => cart.applyDiscount(150), {
        name: 'RangeError',
        message: /150/,
      });
    });

    it('bug 5: rejects a discount just above 100', () => {
      assert.throws(() => cart.applyDiscount(100.01), RangeError);
    });

    it('bug 5: rejects a negative discount with a RangeError', () => {
      assert.throws(() => cart.applyDiscount(-10), {
        name: 'RangeError',
        message: /-10/,
      });
    });

    it('bug 5: a rejected discount keeps the previous discount', () => {
      cart.applyDiscount(25);

      assert.throws(() => cart.applyDiscount(150), RangeError);
      assert.throws(() => cart.applyDiscount(-10), RangeError);
      assert.equal(cart.getTotal(), 60);
    });

    for (const [label, percent] of [
      ['NaN', NaN],
      ['Infinity', Infinity],
      ['-Infinity', -Infinity],
      ['a numeric string', '10'],
      ['null', null],
      ['undefined', undefined],
    ]) {
      it(`rejects ${label} with a TypeError`, () => {
        assert.throws(() => cart.applyDiscount(percent), TypeError);
        assert.equal(cart.getTotal(), 80);
      });
    }

    it('replaces an earlier discount instead of stacking it', () => {
      cart.applyDiscount(50);
      cart.applyDiscount(25);

      assert.equal(cart.getTotal(), 60);
    });
  });

  describe('getItemCount', () => {
    it('returns 0 for an empty cart', () => {
      assert.equal(cart.getItemCount(), 0);
    });

    it('counts distinct lines, not units', () => {
      cart.addItem('apple', 1, 5);
      cart.addItem('banana', 1, 3);
      cart.addItem('apple', 1, 2);

      assert.equal(cart.getItemCount(), 2);
    });
  });
});

