'use strict';

const { describe, it, beforeEach } = require('node:test');
const assert = require('node:assert/strict');

const ShoppingCart = require('../src/cart');
const { CartItemNotFoundError } = require('../src/errors');

describe('ShoppingCart edge cases', () => {
  let cart;

  beforeEach(() => {
    cart = new ShoppingCart();
  });

  describe('per-cart isolation', () => {
    it('keeps items and discounts separate between two carts', () => {
      const other = new ShoppingCart();
      cart.addItem('apple', 10, 1);
      cart.applyDiscount(50);
      other.addItem('banana', 4, 1);

      assert.equal(cart.getTotal(), 5);
      assert.equal(other.getTotal(), 4);
      assert.equal(other.getItemCount(), 1);
    });

    it('removing from one cart does not affect another', () => {
      const other = new ShoppingCart();
      cart.addItem('apple', 10, 1);
      other.addItem('apple', 10, 1);

      cart.removeItem('apple');

      assert.equal(cart.getItemCount(), 0);
      assert.equal(other.getItemCount(), 1);
    });
  });

  describe('quantity limits', () => {
    it('accepts Number.MAX_SAFE_INTEGER as a quantity', () => {
      cart.addItem('bolt', 0, Number.MAX_SAFE_INTEGER);

      assert.equal(cart.items[0].quantity, Number.MAX_SAFE_INTEGER);
    });

    it('rejects a quantity above Number.MAX_SAFE_INTEGER', () => {
      assert.throws(() => cart.addItem('bolt', 1, 2 ** 53), RangeError);
      assert.equal(cart.getItemCount(), 0);
    });

    it('rejects a merge that would push the quantity past Number.MAX_SAFE_INTEGER', () => {
      cart.addItem('bolt', 0, Number.MAX_SAFE_INTEGER);

      assert.throws(() => cart.addItem('bolt', 0, 1), {
        name: 'RangeError',
        message: /bolt/,
      });
      assert.equal(cart.items[0].quantity, Number.MAX_SAFE_INTEGER);
    });
  });

  describe('invalid argument types', () => {
    const nonNumbers = [
      ['null', null],
      ['a boolean', true],
      ['a BigInt', 10n],
      ['an object', { value: 1 }],
      ['an array', [1]],
      ['-Infinity', -Infinity],
    ];

    for (const [label, value] of nonNumbers) {
      it(`addItem rejects ${label} as a price or quantity and leaves the cart empty`, () => {
        assert.throws(() => cart.addItem('apple', value, 1), TypeError);
        assert.throws(() => cart.addItem('apple', 1, value), TypeError);
        assert.equal(cart.getItemCount(), 0);
      });
    }

    for (const [label, name] of [
      ['null', null],
      ['a number', 7],
      ['an object', { name: 'apple' }],
    ]) {
      it(`addItem and removeItem reject ${label} as a name`, () => {
        assert.throws(() => cart.addItem(name, 1, 1), TypeError);
        assert.throws(() => cart.removeItem(name), TypeError);
      });
    }

    it('removeItem rejects an empty or whitespace-only name', () => {
      assert.throws(() => cart.removeItem(''), RangeError);
      assert.throws(() => cart.removeItem('\t\n '), RangeError);
    });

    it('error messages name the argument and the received value', () => {
      assert.throws(() => cart.addItem('apple', '10', 1), {
        message: /price.*"10"/i,
      });
      assert.throws(() => cart.addItem('apple', 1, null), {
        message: /quantity.*null/i,
      });
      assert.throws(() => cart.applyDiscount({}), {
        message: /discount.*object/i,
      });
    });
  });

  describe('names', () => {
    it('supports unicode names end to end', () => {
      cart.addItem('café au lait', 3, 1);
      cart.addItem('日本茶', 4, 1);
      cart.addItem('🍎', 1, 2);

      cart.removeItem('日本茶');

      assert.deepEqual(
        cart.items.map((item) => item.name),
        ['café au lait', '🍎'],
      );
      assert.equal(cart.getTotal(), 5);
    });

    it('compares names exactly, so NFC and NFD spellings of café are separate lines', () => {
      const composed = 'café';
      const decomposed = 'café';
      cart.addItem(composed, 1, 1);
      cart.addItem(decomposed, 1, 1);

      assert.equal(cart.getItemCount(), 2);
    });

    it('treats surrounding whitespace as part of the name', () => {
      cart.addItem('apple', 1, 1);
      cart.addItem(' apple ', 1, 1);

      assert.equal(cart.getItemCount(), 2);
      assert.throws(() => cart.removeItem('apple  '), CartItemNotFoundError);
    });

    it('handles very long names', () => {
      const longName = 'x'.repeat(5000);
      cart.addItem(longName, 2, 1);
      cart.addItem(longName, 2, 1);

      assert.equal(cart.getItemCount(), 1);
      cart.removeItem(longName);
      assert.equal(cart.getItemCount(), 0);
    });
  });

  describe('burst and volume', () => {
    it('totals 10,000 distinct lines correctly', () => {
      for (let i = 0; i < 10_000; i++) {
        cart.addItem(`item-${i}`, 1, 2);
      }

      assert.equal(cart.getItemCount(), 10_000);
      assert.equal(cart.getTotal(), 20_000);
    });

    it('merges 10,000 rapid adds of the same item into one line', () => {
      for (let i = 0; i < 10_000; i++) {
        cart.addItem('apple', 0.5, 1);
      }

      assert.equal(cart.getItemCount(), 1);
      assert.equal(cart.getTotal(), 5_000);
    });

    it('rejects every invalid add in a burst without corrupting valid ones', () => {
      for (let i = 0; i < 100; i++) {
        cart.addItem('apple', 1, 1);
        assert.throws(() => cart.addItem('apple', 1, -1), RangeError);
      }

      assert.equal(cart.items[0].quantity, 100);
    });
  });

  describe('discount boundaries', () => {
    it('a 100% discount on an empty cart totals 0', () => {
      cart.applyDiscount(100);

      assert.equal(cart.getTotal(), 0);
    });

    it('a discount on free items totals 0', () => {
      cart.addItem('sticker', 0, 10);
      cart.applyDiscount(30);

      assert.equal(cart.getTotal(), 0);
    });

    it('rejects a discount just below 0', () => {
      assert.throws(() => cart.applyDiscount(-0.01), RangeError);
    });
  });
});

