const { describe, it, beforeEach } = require('node:test');
const assert = require('node:assert/strict');

const ShoppingCart = require('../src/cart');
const { CartItemNotFoundError } = require('../src/errors');

describe('ShoppingCart edge cases', () => {
  let cart;

  beforeEach(() => {
    cart = new ShoppingCart();
  });

  describe('per-cart isolation', () => {
    it('keeps items and discounts separate between two carts', () => {
      const other = new ShoppingCart();
      cart.addItem('apple', 10, 1);
      cart.applyDiscount(50);
      other.addItem('banana', 4, 1);

      assert.equal(cart.getTotal(), 5);
      assert.equal(other.getTotal(), 4);
      assert.equal(other.getItemCount(), 1);
    });

    it('removing from one cart does not affect another', () => {
      const other = new ShoppingCart();
      cart.addItem('apple', 10, 1);
      other.addItem('apple', 10, 1);

      cart.removeItem('apple');

      assert.equal(cart.getItemCount(), 0);
      assert.equal(other.getItemCount(), 1);
    });
  });

  describe('quantity limits', () => {
    it('accepts Number.MAX_SAFE_INTEGER as a quantity', () => {
      cart.addItem('bolt', 0, Number.MAX_SAFE_INTEGER);

      assert.equal(cart.items[0].quantity, Number.MAX_SAFE_INTEGER);
    });

    it('rejects a quantity above Number.MAX_SAFE_INTEGER', () => {
      assert.throws(() => cart.addItem('bolt', 1, 2 ** 53), RangeError);
      assert.equal(cart.getItemCount(), 0);
    });

    it('rejects a merge that would push the quantity past Number.MAX_SAFE_INTEGER', () => {
      cart.addItem('bolt', 0, Number.MAX_SAFE_INTEGER);

      assert.throws(() => cart.addItem('bolt', 0, 1), {
        name: 'RangeError',
        message: /bolt/,
      });
      assert.equal(cart.items[0].quantity, Number.MAX_SAFE_INTEGER);
    });
  });

  describe('invalid argument types', () => {
    const nonNumbers = [
      ['null', null],
      ['a boolean', true],
      ['a BigInt', 10n],
      ['an object', { value: 1 }],
      ['an array', [1]],
      ['-Infinity', -Infinity],
    ];

    for (const [label, value] of nonNumbers) {
      it(`addItem rejects ${label} as a price or quantity and leaves the cart empty`, () => {
        assert.throws(() => cart.addItem('apple', value, 1), TypeError);
        assert.throws(() => cart.addItem('apple', 1, value), TypeError);
        assert.equal(cart.getItemCount(), 0);
      });
    }

    for (const [label, name] of [
      ['null', null],
      ['a number', 7],
      ['an object', { name: 'apple' }],
    ]) {
      it(`addItem and removeItem reject ${label} as a name`, () => {
        assert.throws(() => cart.addItem(name, 1, 1), TypeError);
        assert.throws(() => cart.removeItem(name), TypeError);
      });
    }

    it('removeItem rejects an empty or whitespace-only name', () => {
      assert.throws(() => cart.removeItem(''), RangeError);
      assert.throws(() => cart.removeItem('\t\n '), RangeError);
