// Goes through the package entry point so the index -> cart -> validation and
// errors wiring is exercised together.
const { ShoppingCart, CartItemNotFoundError } = require('../src');

describe('ShoppingCart via the package entry point', () => {
  it('runs a full checkout flow: add, merge, discount, remove, total', () => {
    const cart = new ShoppingCart();

    cart.addItem('notebook', 4, 2);
    cart.addItem('pen', 1.5, 4);
    cart.addItem('notebook', 4, 1);
    assert.equal(cart.getItemCount(), 2);
    assert.equal(cart.getTotal(), 18);

    cart.applyDiscount(50);
    assert.equal(cart.getTotal(), 9);

    cart.removeItem('pen');
    assert.equal(cart.getItemCount(), 1);
    assert.equal(cart.getTotal(), 6);

    cart.applyDiscount(0);
    assert.equal(cart.getTotal(), 12);
  });

  it('throws the same CartItemNotFoundError class that the entry point exports', () => {
    const cart = new ShoppingCart();

    assert.throws(() => cart.removeItem('ghost'), CartItemNotFoundError);
  });

  it('keeps a consistent state across a session with interleaved failures', () => {
    const cart = new ShoppingCart();
    const attempts = [
      () => cart.addItem('mug', 8, 2),
      () => cart.addItem('mug', -8, 1),
      () => cart.applyDiscount(150),
      () => cart.addItem('tea', 2.5, 4),
      () => cart.removeItem('coffee'),
      () => cart.applyDiscount(25),
      () => cart.addItem('tea', 2.5, 0),
    ];

    const failures = [];
    for (const attempt of attempts) {
      try {
        attempt();
      } catch (error) {
        failures.push(error.name);
      }
    }

    assert.deepEqual(failures, ['RangeError', 'RangeError', 'CartItemNotFoundError', 'RangeError']);
    assert.equal(cart.getItemCount(), 2);
    assert.equal(cart.getTotal(), 19.5);
  });
});

