'use strict';

/** Lowest discount `applyDiscount` accepts, in percent. */
const MIN_DISCOUNT_PERCENT = 0;
/** Highest discount `applyDiscount` accepts, in percent. */
const MAX_DISCOUNT_PERCENT = 100;

// Renders a rejected value for an error message. Strings are quoted so that
// "10" and 10 read differently; objects collapse to their type to keep
// messages short and to avoid echoing arbitrary caller data.
function describeValue(value) {
  if (typeof value === 'string') return JSON.stringify(value);
  if (typeof value === 'number') return String(value);
  if (value === null) return 'null';
  if (Array.isArray(value)) return 'array';
  return typeof value;
}

/**
 * @param {unknown} name
 * @throws {TypeError} if `name` is not a string
 * @throws {RangeError} if `name` is empty or whitespace-only
 */
function assertItemName(name) {
  if (typeof name !== 'string') {
    throw new TypeError(`Item name must be a string, received ${describeValue(name)}`);
  }
  if (name.trim() === '') {
    throw new RangeError(`Item name must not be empty or whitespace-only, received ${describeValue(name)}`);
  }
}

/**
 * @param {unknown} price
 * @throws {TypeError} if `price` is not a finite number
 * @throws {RangeError} if `price` is negative
 */
function assertPrice(price) {
  if (!Number.isFinite(price)) {
    throw new TypeError(`Price must be a finite number, received ${describeValue(price)}`);
  }
  if (price < 0) {
    throw new RangeError(`Price must be zero or greater, received ${describeValue(price)}`);
  }
}

/**
 * @param {unknown} quantity
 * @throws {TypeError} if `quantity` is not a finite number
 * @throws {RangeError} if `quantity` is not a whole number from 1 to Number.MAX_SAFE_INTEGER
 */
function assertQuantity(quantity) {
  if (!Number.isFinite(quantity)) {
    throw new TypeError(`Quantity must be a finite number, received ${describeValue(quantity)}`);
  }
  if (!Number.isSafeInteger(quantity) || quantity < 1) {
    throw new RangeError(
      `Quantity must be a whole number from 1 to ${Number.MAX_SAFE_INTEGER}, received ${describeValue(quantity)}`,
    );
  }
}

/**
 * Checks that adding `added` units to an existing line stays a safe integer.
 * Past Number.MAX_SAFE_INTEGER, addition silently loses precision.
 * @param {string} name
 * @param {number} current
 * @param {number} added
 * @throws {RangeError} if the merged quantity would exceed Number.MAX_SAFE_INTEGER
 */
function assertMergedQuantity(name, current, added) {
  if (!Number.isSafeInteger(current + added)) {
    throw new RangeError(
      `Adding ${added} to ${describeValue(name)} (currently ${current}) would exceed the maximum quantity of ${Number.MAX_SAFE_INTEGER}`,
    );
  }
}

/**
 * @param {unknown} percent
 * @throws {TypeError} if `percent` is not a finite number
 * @throws {RangeError} if `percent` is outside MIN_DISCOUNT_PERCENT..MAX_DISCOUNT_PERCENT
 */
function assertDiscountPercent(percent) {
  if (!Number.isFinite(percent)) {
    throw new TypeError(`Discount must be a finite number, received ${describeValue(percent)}`);
  }
  if (percent < MIN_DISCOUNT_PERCENT || percent > MAX_DISCOUNT_PERCENT) {
    throw new RangeError(
      `Discount must be between ${MIN_DISCOUNT_PERCENT} and ${MAX_DISCOUNT_PERCENT} percent, received ${describeValue(percent)}`,
    );
  }
}

module.exports = {
  MIN_DISCOUNT_PERCENT,
  MAX_DISCOUNT_PERCENT,
  assertItemName,
  assertPrice,
  assertQuantity,
  assertMergedQuantity,
  assertDiscountPercent,
};

