'use strict';

const { CartItemNotFoundError } = require('./errors');
const {
  assertItemName,
  assertPrice,
  assertQuantity,
  assertMergedQuantity,
  assertDiscountPercent,
} = require('./validation');

/**
 * In-memory shopping cart. Each instance holds its own items and discount.
 * Every mutating method validates its arguments before changing state, so a
 * call that throws leaves the cart exactly as it was.
 */
class ShoppingCart {
  constructor() {
    /** @type {{ name: string, price: number, quantity: number }[]} */
    this.items = [];
    /** Discount in percent, from 0 to 100. */
    this.discount = 0;
  }

  /**
   * Adds a line item. If an item with the same name is already in the cart,
   * its quantity grows and the price from the first add is kept.
   * @param {string} name non-empty; compared exactly (case- and whitespace-sensitive)
   * @param {number} price finite, zero or greater
   * @param {number} quantity whole number, 1 or greater
