'use strict';
const fs = require('node:fs');
const [file, bug] = process.argv.slice(2);
let src = fs.readFileSync(file, 'utf8');
const swaps = {
  1: [['    assertPrice(price);\n    assertQuantity(quantity);\n', '']],
  2: [[/assertItemName\(name\);\n\n    const index[\s\S]*?this\.items\.splice\(index, 1\);/, 'this.items = this.items.filter(i => i.name = name);']],
  3: [[/const subtotal = this\.items\.reduce[^\n]*\n/, 'let subtotal = 0;\n    for (let i = 0; i <= this.items.length; i++) { subtotal += this.items[i].price * this.items[i].quantity; }\n']],
  4: [['return subtotal - (', 'return subtotal + (']],
  5: [['    assertDiscountPercent(percent);\n', '']],
};
for (const [from, to] of swaps[bug]) {
  const next = src.replace(from, to);
  if (next === src) { console.error(`mutation for bug ${bug} did not apply`); process.exit(2); }
  src = next;
}
fs.writeFileSync(file, src);
EOF
for bug in 1 2 3 4 5; do
  rm -rf "$SCRATCH/repo" && mkdir "$SCRATCH/repo" && cp -R package.json src tests "$SCRATCH/repo/"
